// Des: Split and canonicalize http(s) URLs for dedupe
// Flo: trim > check scheme > split host/port/path/query > drop fragment and tracking params > sort query > rebuild
// I/O: raw URL text (frontier, redirects) > Part struct or canonical URL string (caller owns)
// ===================================================================
const std = @import("std"); const mem2 = std.mem;
const CF = .{ .maxl = 2048, .trak = @as([]const []const u8, &.{ "utm_", "fbclid", "gclid", "msclkid", "mc_cid", "mc_eid", "igshid", "yclid", "_ga" }) };
pub const Part = struct { sche: []const u8, host: []const u8, port: u16, path: []const u8, quer: []const u8, dflt: bool };
pub fn urlzSpli(raws: []const u8) !Part { const text = mem2.trim(u8, raws, " \t\r\n"); if (text.len == 0 or text.len > CF.maxl) return error.BadUrl; for (text) |byte| if (byte < 0x21 or byte == 0x7f) return error.BadUrl; const sepz = mem2.find(u8, text, "://") orelse return error.BadUrl; const sche = text[0..sepz]; const ishp = std.ascii.eqlIgnoreCase(sche, "http"); if (!ishp and !std.ascii.eqlIgnoreCase(sche, "https")) return error.BadUrl; var rest = text[sepz + 3 ..]; if (mem2.findScalar(u8, rest, '#')) |hash| rest = rest[0..hash]; const endz = mem2.findAny(u8, rest, "/?") orelse rest.len; const auth = rest[0..endz]; if (auth.len == 0 or mem2.findScalar(u8, auth, '@') != null) return error.BadUrl; var host = auth; var por3: ?u16 = null; if (auth[0] == '[') { const clos = mem2.findScalar(u8, auth, ']') orelse return error.BadUrl; host = auth[0 .. clos + 1]; if (clos + 1 < auth.len) { if (auth[clos + 1] != ':') return error.BadUrl; por3 = std.fmt.parseInt(u16, auth[clos + 2 ..], 10) catch return error.BadUrl; } } else if (mem2.findScalar(u8, auth, ':')) |colo| { host = auth[0..colo]; por3 = std.fmt.parseInt(u16, auth[colo + 1 ..], 10) catch return error.BadUrl; } if (host.len == 0 or (por3 != null and por3.? == 0)) return error.BadUrl; const tail = rest[endz..]; const qidx = mem2.findScalar(u8, tail, '?'); const path = if (qidx) |qizz| tail[0..qizz] else tail; const quer = if (qidx) |qizz| tail[qizz + 1 ..] else ""; const dpor: u16 = if (ishp) 80 else 443; return .{ .sche = if (ishp) "http" else "https", .host = host, .port = por3 orelse dpor, .path = if (path.len == 0) "/" else path, .quer = quer, .dflt = (por3 orelse dpor) == dpor }; }
fn trakIszz(pair: []const u8) bool { for (CF.trak) |pref| if (mem2.startsWith(u8, pair, pref)) return true; return false; }
fn lessPair(_: void, left: []const u8, rite: []const u8) bool { return mem2.lessThan(u8, left, rite); }
pub fn urlzNorm(allo: std.mem.Allocator, raws: []const u8) ![]u8 { const part = try urlzSpli(raws); var pair: std.ArrayList([]const u8) = .empty; defer pair.deinit(allo); var iter = mem2.splitScalar(u8, part.quer, '&'); while (iter.next()) |item| { if (item.len == 0 or trakIszz(item)) continue; try pair.append(allo, item); } mem2.sort([]const u8, pair.items, {}, lessPair); const quer = try mem2.join(allo, "&", pair.items); defer allo.free(quer); const hos2 = try std.ascii.allocLowerString(allo, part.host); defer allo.free(hos2); const por2 = if (part.dflt) try allo.dupe(u8, "") else try std.fmt.allocPrint(allo, ":{d}", .{part.port}); defer allo.free(por2); const qsep: []const u8 = if (quer.len > 0) "?" else ""; return std.fmt.allocPrint(allo, "{s}://{s}{s}{s}{s}{s}", .{ part.sche, hos2, por2, part.path, qsep, quer }); }
